#!/usr/bin/env python3
"""Draw a simple sunrise-temple picture (no copyright issues: generated by code) for testing the cover tool.

    python scripts/make_sample_cover.py            -> samples/cover_sample.jpg  (1920x1080)
"""
import math
import random
from pathlib import Path

from PIL import Image, ImageDraw, ImageFilter

W, H = 1920, 1080
OUT = Path(__file__).resolve().parents[1] / "samples" / "cover_sample.jpg"


def lerp(a, b, t):
    return tuple(int(a[i] + (b[i] - a[i]) * t) for i in range(3))


def main() -> None:
    rnd = random.Random(7)
    img = Image.new("RGB", (W, H))
    px = ImageDraw.Draw(img)
    stops = [(0.0, (18, 24, 86)), (0.45, (140, 60, 120)), (0.72, (255, 140, 70)), (1.0, (255, 210, 120))]
    for y in range(H):
        f = y / (H - 1)
        for (f0, c0), (f1, c1) in zip(stops, stops[1:]):
            if f0 <= f <= f1:
                px.line([(0, y), (W, y)], fill=lerp(c0, c1, (f - f0) / (f1 - f0)))
                break
    # sun
    sun = Image.new("RGB", (W, H), (0, 0, 0))
    sd = ImageDraw.Draw(sun)
    sd.ellipse([W / 2 - 150, H * 0.56 - 150, W / 2 + 150, H * 0.56 + 150], fill=(255, 236, 170))
    sun = sun.filter(ImageFilter.GaussianBlur(40))
    img = Image.composite(Image.blend(img, sun, 0.85), img, sun.convert("L").point(lambda v: min(255, v * 2)))
    d = ImageDraw.Draw(img)
    # reflective water
    d.rectangle([0, H * 0.78, W, H], fill=(40, 30, 70))
    for i in range(160):
        y = rnd.randint(int(H * 0.78), H)
        x = rnd.randint(0, W)
        d.line([(x, y), (x + rnd.randint(30, 120), y)], fill=(255, 190, 120), width=1)
    # temple silhouette: five stepped towers
    ink = (16, 10, 30)
    base_y = H * 0.78
    d.rectangle([W * 0.18, base_y - 70, W * 0.82, base_y], fill=ink)  # terrace

    def tower(cx, height, width):
        steps = 6
        for s in range(steps):
            w = width * (1 - s / (steps + 1.5))
            h0 = base_y - 70 - s * (height / steps)
            d.rectangle([cx - w / 2, h0 - height / steps, cx + w / 2, h0], fill=ink)
        tip = base_y - 70 - height
        d.polygon([(cx - width * 0.12, tip), (cx + width * 0.12, tip), (cx, tip - height * 0.28)], fill=ink)

    tower(W * 0.5, 330, 170)
    for cx, hh in ((W * 0.5 - 250, 240), (W * 0.5 + 250, 240), (W * 0.5 - 430, 170), (W * 0.5 + 430, 170)):
        tower(cx, hh, 120 if hh > 200 else 95)
    # palms
    for cx in (W * 0.08, W * 0.93):
        d.rectangle([cx - 7, H * 0.52, cx + 7, base_y], fill=ink)
        for ang in range(-70, 71, 28):
            a = math.radians(ang - 90)
            d.line([(cx, H * 0.52), (cx + math.cos(a) * 150, H * 0.52 + math.sin(a) * 90)], fill=ink, width=9)
    OUT.parent.mkdir(parents=True, exist_ok=True)
    img.save(OUT, "JPEG", quality=88)
    print("wrote", OUT, OUT.stat().st_size // 1024, "KB")


if __name__ == "__main__":
    main()
